import {
  type ReactNode,
  type Ref,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { type TamaguiElement, View } from 'tamagui/unstyled'
import { ScrollArea, type ScrollAreaProps } from '../scroll-area/ScrollArea'
import { type ItemHeight, heightOf, indexAt, itemOffsets } from './offsets'

export interface VirtualListProps<T> extends Omit<ScrollAreaProps, 'children' | 'orientation'> {
  data: readonly T[]
  /** Draws one row. With `itemHeight` it gets that height, so keep its content to it. */
  renderItem: (item: T, index: number) => ReactNode
  /**
   * Row height in pixels: one number for every row, or a function of the
   * index. Leave it out for rows that size themselves: they are measured once
   * drawn, with `estimatedItemHeight` until then.
   */
  itemHeight?: ItemHeight
  /** Rows that size themselves: the height of a row not yet measured. Default 48. */
  estimatedItemHeight?: number
  /** A stable key per row, such as its id. Default: the index. */
  getItemKey?: (item: T, index: number) => string | number
  /** Rows drawn above and below the visible ones, so fast scrolling shows no gap. Web only. */
  overscan?: number
  /** Rows drawn before the list is measured: on the server and in the first frame. */
  initialCount?: number
  /** Called once per length of `data` when the end comes near, to load more. */
  onEndReached?: () => void
  /** How near the end `onEndReached` fires, in visible heights. Default 0.5. */
  onEndReachedThreshold?: number
  /** Shown after the last row, such as a loading row. */
  footer?: ReactNode
  /** Shown instead of the list when `data` is empty. */
  empty?: ReactNode
  ref?: Ref<TamaguiElement>
}

type ScrollEvent = { currentTarget: HTMLElement }

type Row = { key: string | number; index: number }

/**
 * A long list that draws only the rows in view, so thousands of rows scroll
 * smoothly. Web windows the rows itself in a ScrollArea; iOS and Android use
 * React Native's FlatList. Rows that size themselves are measured as they
 * are drawn; when one above the view changes height, the list scrolls by as
 * much, so what is in view stays put.
 */
export function VirtualList<T>({
  data,
  renderItem,
  itemHeight,
  estimatedItemHeight = 48,
  getItemKey,
  overscan = 4,
  initialCount = 10,
  onEndReached,
  onEndReachedThreshold = 0.5,
  footer,
  empty,
  ref,
  onScroll,
  ...props
}: VirtualListProps<T>) {
  const count = data.length
  const keyOf = (index: number) => (getItemKey ? getItemKey(data[index]!, index) : index)
  const measuring = itemHeight === undefined
  // Rows that size themselves: their heights by key, so they survive rows
  // added above, and a version that moves the rows when one changes.
  const measured = useRef(new Map<string | number, number>())
  const [measuredVersion, setMeasuredVersion] = useState(0)
  const offsets = useMemo(
    () =>
      itemOffsets(
        count,
        itemHeight ?? ((index) => measured.current.get(keyOf(index)) ?? estimatedItemHeight),
      ),
    // keyOf reads data and getItemKey.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [count, itemHeight, estimatedItemHeight, measuredVersion, data, getItemKey],
  )
  const offsetsRef = useRef(offsets)
  offsetsRef.current = offsets
  const scrollRef = useRef<HTMLElement | null>(null)
  const rowRefs = useRef(new Map<number, HTMLElement>())
  // Unknown until measured, after the first render (and on the server).
  const [view, setView] = useState<{ top: number; height: number } | null>(null)
  // A row that holds focus stays drawn when scrolled away, or focus would be lost.
  const [focusIndex, setFocusIndex] = useState<number | null>(null)
  const endCalledFor = useRef(-1)
  const handlers = useRef({ onEndReached, onEndReachedThreshold })
  handlers.current = { onEndReached, onEndReachedThreshold }

  const check = (node: HTMLElement) => {
    const next = { top: node.scrollTop, height: node.clientHeight }
    setView((prev) => (prev?.top === next.top && prev.height === next.height ? prev : next))
    const { onEndReached: onEnd, onEndReachedThreshold: threshold } = handlers.current
    const distance = node.scrollHeight - next.top - next.height
    if (onEnd && next.height > 0 && distance <= threshold * next.height) {
      if (endCalledFor.current === count) return
      endCalledFor.current = count
      onEnd()
    }
  }

  // The area's height can change with the window; the rows it shows with it.
  useEffect(() => {
    const node = scrollRef.current
    if (!node) return
    check(node)
    const observer = new ResizeObserver(() => check(node))
    observer.observe(node)
    return () => observer.disconnect()
    // `count` too: new rows may still leave the end in view, so ask for more.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [count])

  // Each drawn row's key and index, for the observer that measures them.
  const rows = useRef(new Map<Element, Row>())
  const shift = useRef(0)
  const observer = useRef<ResizeObserver | null>(null)
  useEffect(() => {
    if (!measuring) return
    const resized = new ResizeObserver((entries) => {
      const top = scrollRef.current?.scrollTop ?? 0
      let changed = false
      for (const entry of entries) {
        const row = rows.current.get(entry.target)
        if (!row) continue
        const height = entry.borderBoxSize?.[0]?.blockSize ?? entry.contentRect.height
        const before = measured.current.get(row.key)
        if (before !== undefined && Math.abs(before - height) < 0.5) continue
        measured.current.set(row.key, height)
        changed = true
        // A row that starts above the view: what is in view moves with it.
        if ((offsetsRef.current[row.index] ?? 0) < top) {
          shift.current += height - (before ?? estimatedItemHeight)
        }
      }
      if (changed) setMeasuredVersion((version) => version + 1)
    })
    observer.current = resized
    for (const node of rows.current.keys()) resized.observe(node)
    return () => {
      resized.disconnect()
      observer.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [measuring])
  useLayoutEffect(() => {
    const node = scrollRef.current
    if (!shift.current || !node) return
    node.scrollTop += shift.current
    shift.current = 0
  }, [measuredVersion])

  let start = 0
  let end = Math.min(count, initialCount)
  if (view && view.height > 0) {
    start = Math.max(0, indexAt(offsets, view.top) - overscan)
    end = Math.min(count, indexAt(offsets, view.top + view.height) + 1 + overscan)
  }
  const indices = Array.from({ length: Math.max(0, end - start) }, (_, i) => start + i)
  if (focusIndex !== null && focusIndex < count && (focusIndex < start || focusIndex >= end)) {
    indices.push(focusIndex)
  }

  const setRefs = (node: TamaguiElement | null) => {
    scrollRef.current = node as HTMLElement | null
    if (typeof ref === 'function') ref(node)
    else if (ref) ref.current = node
  }

  return (
    <ScrollArea
      ref={setRefs}
      onScroll={(event: ScrollEvent) => {
        check(event.currentTarget)
        ;(onScroll as ((event: ScrollEvent) => void) | undefined)?.(event)
      }}
      {...props}
    >
      {count === 0 && empty ? (
        empty
      ) : (
        <View>
          <View
            role="list"
            position="relative"
            height={offsets[count]}
            onFocus={(event: { target: EventTarget }) => {
              for (const [index, node] of rowRefs.current) {
                if (node.contains(event.target as Node)) return setFocusIndex(index)
              }
            }}
            onBlur={(event: { currentTarget: HTMLElement; relatedTarget: EventTarget | null }) => {
              if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
                setFocusIndex(null)
              }
            }}
          >
            {indices.map((index) => (
              <View
                key={keyOf(index)}
                ref={(node: TamaguiElement | null) => {
                  const element = node as unknown as HTMLElement | null
                  if (element) {
                    rowRefs.current.set(index, element)
                    if (measuring && !rows.current.has(element)) observer.current?.observe(element)
                    rows.current.set(element, { key: keyOf(index), index })
                  } else {
                    const old = rowRefs.current.get(index)
                    rowRefs.current.delete(index)
                    if (old) {
                      observer.current?.unobserve(old)
                      rows.current.delete(old)
                    }
                  }
                }}
                role="listitem"
                // The list holds only the drawn rows: these tell screen
                // readers where each one is in the whole list.
                aria-posinset={index + 1}
                aria-setsize={count}
                position="absolute"
                top={offsets[index]}
                left={0}
                right={0}
                {...(itemHeight !== undefined && { height: heightOf(itemHeight, index) })}
              >
                {renderItem(data[index]!, index)}
              </View>
            ))}
          </View>
          {footer}
        </View>
      )}
    </ScrollArea>
  )
}

import { type Context, useMemo } from 'react'
import { FlatList, ScrollView } from 'react-native'
import { View } from 'tamagui/unstyled'
import { heightOf, itemOffsets } from './offsets'
import type { VirtualListProps } from './VirtualList'

// React Native warns about a list inside a scroll view that scrolls the same
// way, as such a list often has no height and draws every row. This one has
// its frame's height and keeps its window, so it hides the scroll view around.
const ParentScrollView = (ScrollView as unknown as { Context: Context<unknown> }).Context

/**
 * Native: React Native's FlatList, which keeps its own window of rows. The
 * frame takes the style props (height, border…) and the list fills it. Rows
 * that size themselves are measured by FlatList as it draws them.
 */
export function VirtualList<T>({
  data,
  renderItem,
  itemHeight,
  estimatedItemHeight: _estimatedItemHeight,
  getItemKey,
  overscan: _overscan,
  initialCount = 10,
  onEndReached,
  onEndReachedThreshold = 0.5,
  footer,
  empty,
  ref,
  onScroll,
  'aria-label': label,
  ...props
}: VirtualListProps<T>) {
  const offsets = useMemo(
    () => (itemHeight === undefined ? null : itemOffsets(data.length, itemHeight)),
    [data.length, itemHeight],
  )
  return (
    <View ref={ref} {...props}>
      <ParentScrollView.Provider value={null}>
        <FlatList
          data={data}
          // `flex: 1` fills the frame, whatever height it is given.
          style={{ flex: 1 }}
          renderItem={({ item, index }) =>
            itemHeight === undefined ? (
              <View>{renderItem(item, index)}</View>
            ) : (
              <View height={heightOf(itemHeight, index)}>{renderItem(item, index)}</View>
            )
          }
          keyExtractor={(item, index) => String(getItemKey ? getItemKey(item, index) : index)}
          // Known heights: FlatList places rows without measuring them, and
          // scrolls straight to any of them. Otherwise it measures them.
          {...(itemHeight !== undefined &&
            offsets && {
              getItemLayout: (_: unknown, index: number) => ({
                length: heightOf(itemHeight, index),
                offset: offsets[index]!,
                index,
              }),
            })}
          initialNumToRender={initialCount}
          onEndReached={onEndReached ? () => onEndReached() : undefined}
          onEndReachedThreshold={onEndReachedThreshold}
          ListFooterComponent={footer ? <>{footer}</> : null}
          ListEmptyComponent={empty ? <>{empty}</> : null}
          onScroll={onScroll as never}
          scrollEventThrottle={16}
          // Android: without it, a list inside a scrolling screen never
          // scrolls; the screen takes every vertical drag.
          nestedScrollEnabled
          // React Native's ScrollView drops aria-label.
          accessibilityLabel={label}
        />
      </ParentScrollView.Provider>
    </View>
  )
}

/** Row height in pixels: one for every row, or one per row. */
export type ItemHeight = number | ((index: number) => number)

export const heightOf = (itemHeight: ItemHeight, index: number) =>
  typeof itemHeight === 'number' ? itemHeight : itemHeight(index)

/** Where each row starts, plus the total height as the last entry. */
export function itemOffsets(count: number, itemHeight: ItemHeight) {
  const offsets = new Array<number>(count + 1)
  offsets[0] = 0
  for (let i = 0; i < count; i++) offsets[i + 1] = offsets[i]! + heightOf(itemHeight, i)
  return offsets
}

/** The row at `y` pixels from the top, found by halving: lists can be long. */
export function indexAt(offsets: readonly number[], y: number) {
  let low = 0
  let high = offsets.length - 2
  while (low < high) {
    const mid = (low + high + 1) >> 1
    if (offsets[mid]! <= y) low = mid
    else high = mid - 1
  }
  return Math.max(0, low)
}

